// Array of Marketing Studio generations. Absent on error.
items?: Array<
{
author?: {
avatarUrl?: string,
userId: string, // minLength: 1
username?: string,
},
batch_id?: string,
createdAt?: number,
folder_id?: string, // pattern: /^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$/, format: "uuid"
id: string, // minLength: 1
liked?: boolean,
model: string,
params: {
aspect_ratio?: string | null,
custom_reference_id?: (string | { [key: string]: any }) | null,
duration?: number | null,
image?: string | null,
input_images?: { id?: string, type?: string, url?: string, [key: string]: any }[] | null,
medias?: { data?: { id?: string, type?: string, url?: string, [key: string]: any }, role?: string, [key: string]: any }[] | null,
presetMeta?: { id?: string, name?: string, url?: string } | null,
prompt: string, // default: ""
reference_images?: Array<string | { [key: string]: any }> | null,
