results?: {
autosprite?: { atlasUrl?: string, audioUrl?: string, columns?: number, frameCount?: number, frameHeight?: number, frameWidth?: number, spritesheetId?: string },
durationSec?: number,
// Original EXR ZIP; when present, rawUrl is the unprocessed input video used for playback.
exrUrl?: string,
height?: number,
